\begin{equation}
(\dagger) \quad
\begin{array}{ll}
x_n'(t) &= \, y_n(t) \, - \, y_{n-1}(t) \\
y_n'(t) &= \, y_n(t) \big( x_{n+1}(t) \, - \, x_n(t) \big) 
